const { to } = trigger.data;
const res = await fetch(process.env.VORTEX_API_URL, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${process.env.VORTEX_API_KEY}`
  },
  body: JSON.stringify({
    query: `query CheckSuppression($email: String!) {
      emailSuppressions(condition: { email: $email }) {
        totalCount
      }
    }`,
    variables: { email: to }
  })
});
const json = await res.json();
const count = json.data?.emailSuppressions?.totalCount ?? 0;
return { suppressed: count > 0 };

const { templateId, templateData } = trigger.data;
const res = await fetch(`${process.env.GATEKEEPER_API_URL}/api/email/render`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${process.env.EMAIL_RENDER_SECRET}`
  },
  body: JSON.stringify({ templateId, templateData })
});
if (!res.ok) throw new Error(`Render failed: ${res.status}`);
const json = await res.json();
return { html: json.html, subject: json.subject };

const { to, senderAddress } = trigger.data;
const { html, subject } = steps['render'].output;
const res = await fetch('https://api.resend.com/emails', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${process.env.RESEND_API_KEY}`
  },
  body: JSON.stringify({
    from: senderAddress,
    to: [to],
    subject,
    html
  })
});
if (!res.ok) throw new Error(`Resend failed: ${res.status}`);
const json = await res.json();
return { messageId: json.id };
